<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ArrowLeft, ArrowRight, CheckCircle2, CirclePlus, FileCheck2, Package, Save, Send, Trash2, Truck, UserRound } from '@lucide/vue'
import { useRouter } from 'vue-router'
import { api, apiError } from '../services/api'
import { useToastStore } from '../stores/toast'
import SearchCombobox from '../components/SearchCombobox.vue'
import CurrencyInput from '../components/CurrencyInput.vue'

const router = useRouter()
const toast = useToastStore()
const loading = ref(true)
const saving = ref(false)
const step = ref(1)
const naturezas = ref<Record<string, any>[]>([])
const selectedRecipient = ref<Record<string, any> | null>(null)
const selectedProduct = ref<Record<string, any> | null>(null)
const errors = ref<Record<string, string[]>>({})
const form = reactive<Record<string, any>>({ serie: 1, numero: '', id_natureza_operacao: '', id_cliente: '', id_destinatario: '', finalidade: '1', ind_pres: 9, consumidor_final: true, data_emissao: new Date().toISOString().slice(0, 10), hora_emissao: new Date().toTimeString().slice(0, 5), desconto: 0, outras_despesas: 0, informacoes_complementares: '', transportadora: { modalidade_frete: '9', nome: '', documento: '', placa: '', uf_veiculo: '' }, volumes: { quantidade: 0, especie: '', peso_bruto: 0, peso_liquido: 0 }, produtos: [] })
const steps = [{ id: 1, label: 'Operação', icon: FileCheck2 }, { id: 2, label: 'Destinatário', icon: UserRound }, { id: 3, label: 'Itens', icon: Package }, { id: 4, label: 'Transporte', icon: Truck }, { id: 5, label: 'Revisão', icon: CheckCircle2 }]
const natureza = computed(() => naturezas.value.find((item) => String(item.id) === String(form.id_natureza_operacao)))
const recipient = computed(() => selectedRecipient.value)
const subtotal = computed(() => form.produtos.reduce((total: number, item: any) => total + Number(item.quantidade || 0) * Number(item.valor_unitario || 0), 0))
const total = computed(() => Math.max(0, subtotal.value - Number(form.desconto || 0) + Number(form.outras_despesas || 0)))
const money = (value: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value)
const document = (value?: string) => value || 'Documento não informado'

watch(selectedRecipient, (value) => {
  form.id_cliente = value?.type === 'cliente' ? value.entity_id : ''
  form.id_destinatario = value?.type === 'fornecedor' ? value.entity_id : ''
})

onMounted(async () => {
  try {
    const [natureResponse, numberResponse] = await Promise.all([
      api.get('/naturezas-operacao', { params: { page: 1, per_page: 100, all: true } }), api.get('/nfe/proximo-numero', { params: { serie: form.serie } }),
    ])
    naturezas.value = natureResponse.data.data || natureResponse.data
    form.numero = numberResponse.data.numero
  } catch (error) { toast.show('error', apiError(error).message) } finally { loading.value = false }
})

function addProduct() {
  const product = selectedProduct.value; if (!product) return
  const existing = form.produtos.find((item: any) => item.id === product.id)
  if (existing) existing.quantidade += 1
  else form.produtos.push({ id: product.id, codigo: product.codigo, descricao: product.descricao, ncm: product.ncm, cfop: product.cfop || natureza.value?.cfop_padrao || '', unidade: product.unidade || 'UN', quantidade: 1, valor_unitario: Number(product.valor_unitario || 0), csosn: product.csosn || natureza.value?.csosn_padrao || '', cst: product.cst || natureza.value?.cst_padrao || '', origem: 0 })
  selectedProduct.value = null
}
function applyNature() { form.produtos.forEach((item: any) => { item.cfop = item.cfop || natureza.value?.cfop_padrao || ''; item.csosn = item.csosn || natureza.value?.csosn_padrao || ''; item.cst = item.cst || natureza.value?.cst_padrao || '' }) }
function validateCurrent() {
  if (step.value === 1 && !form.id_natureza_operacao) return 'Selecione uma natureza de operação.'
  if (step.value === 2 && !form.id_cliente && !form.id_destinatario) return 'Selecione o destinatário da nota.'
  if (step.value === 3 && !form.produtos.length) return 'Adicione pelo menos um produto.'
  if (step.value === 3 && form.produtos.some((item: any) => !item.ncm || !item.cfop || (!item.csosn && !item.cst) || Number(item.quantidade) < 1)) return 'Revise NCM, CFOP, tributação e quantidade dos itens.'
  if (step.value === 3 && Number(form.desconto || 0) > subtotal.value) return 'O desconto não pode ser maior que o subtotal dos produtos.'
  if (step.value === 3 && (Number(form.desconto || 0) < 0 || Number(form.outras_despesas || 0) < 0)) return 'Desconto e outras despesas não podem ser negativos.'
  return ''
}
function next() { const message = validateCurrent(); if (message) return toast.show('warning', message, 'Etapa incompleta'); step.value = Math.min(5, step.value + 1) }
async function submit(mode: 'rascunho' | 'emitir') {
  const current = step.value; for (const target of [1, 2, 3]) { step.value = target; const message = validateCurrent(); if (message) { toast.show('warning', message, 'Dados obrigatórios'); return } } step.value = current
  saving.value = true; errors.value = {}
  try {
    const payload = { ...form, modo: mode, numero: Number(form.numero), serie: Number(form.serie), id_natureza_operacao: Number(form.id_natureza_operacao), id_cliente: form.id_cliente ? Number(form.id_cliente) : null, id_destinatario: form.id_destinatario ? Number(form.id_destinatario) : null, ind_pres: Number(form.ind_pres), desconto: Number(form.desconto), outras_despesas: Number(form.outras_despesas), produtos: form.produtos.map(({ id, ...item }: any) => ({ ...item, quantidade: Number(item.quantidade), valor_unitario: Number(item.valor_unitario) })), calculo_automatico: true, pagamento: { tpag: '90' }, tipo_saida: 'propria' }
    const { data } = await api.post('/nfe', payload)
    toast.show('success', data.message || (mode === 'rascunho' ? 'NF-e salva como pendente.' : 'NF-e processada com sucesso.'))
    await router.push('/dashboard/notas')
  } catch (error) { const parsed = apiError(error); errors.value = parsed.errors; toast.show('error', parsed.message) } finally { saving.value = false }
}
</script>

<template>
  <div class="invoice-create-page">
    <header class="page-heading"><div><span class="eyebrow">Documentos fiscais</span><h1>Nova NF-e</h1><p>Preencha os dados por etapas e revise antes da transmissão.</p></div><span class="draft-number">Série {{ form.serie }} · Nº {{ form.numero || '—' }}</span></header>
    <nav class="invoice-steps"><button v-for="item in steps" :key="item.id" :class="{ active: step === item.id, complete: step > item.id }" @click="step = item.id"><span><CheckCircle2 v-if="step > item.id" :size="18" /><component :is="item.icon" v-else :size="18" /></span><small>Etapa {{ item.id }}</small><strong>{{ item.label }}</strong></button></nav>
    <section class="panel invoice-form-panel" :class="{ 'is-loading': loading }">
      <div v-if="step === 1" class="invoice-step-content"><div class="section-title"><span><FileCheck2 :size="21" /></span><div><h2>Dados da operação</h2><p>Defina a natureza, numeração e finalidade do documento.</p></div></div><div class="settings-form"><label class="field-span-2"><span>Natureza de operação *</span><select v-model="form.id_natureza_operacao" @change="applyNature"><option value="" disabled>Selecione a natureza</option><option v-for="item in naturezas" :key="item.id" :value="item.id">{{ item.nome }} · CFOP {{ item.cfop_padrao }}</option></select></label><label><span>Série *</span><input v-model.number="form.serie" type="number" min="1" max="999"></label><label><span>Número *</span><input v-model.number="form.numero" type="number" min="1"></label><label><span>Data de emissão</span><input v-model="form.data_emissao" type="date"></label><label><span>Hora de emissão</span><input v-model="form.hora_emissao" type="time"></label><label><span>Finalidade</span><select v-model="form.finalidade"><option value="1">NF-e normal</option><option value="2">Complementar</option><option value="3">Ajuste</option><option value="4">Devolução</option></select></label><label><span>Indicador de presença</span><select v-model="form.ind_pres"><option :value="0">Não se aplica</option><option :value="1">Operação presencial</option><option :value="2">Internet</option><option :value="9">Outros</option></select></label></div></div>
      <div v-else-if="step === 2" class="invoice-step-content"><div class="section-title"><span><UserRound :size="21" /></span><div><h2>Destinatário</h2><p>Busque clientes e fornecedores por razão social, CPF ou CNPJ.</p></div></div><div class="settings-form"><label class="field-span-2"><span>Empresa destinatária *</span><SearchCombobox v-model="selectedRecipient" endpoint="/nfe/destinatarios" label-key="name" placeholder="Buscar cliente ou fornecedor" search-placeholder="Digite razão social, CPF ou CNPJ…" empty-text="Nenhuma empresa ativa encontrada."><template #selected="{ option }"><span class="selected-search-value"><strong>{{ option.name }}</strong><small>{{ document(option.documento) }} · {{ option.type === 'fornecedor' ? 'Fornecedor' : 'Cliente' }}</small></span></template><template #option="{ option }"><span class="search-option"><span class="option-avatar" :class="{ supplier: option.type === 'fornecedor' }">{{ option.name?.slice(0, 2).toUpperCase() }}</span><span class="search-option-main"><strong>{{ option.name }}</strong><small>{{ document(option.documento) }}<template v-if="option.cidade"> · {{ option.cidade }}/{{ option.uf }}</template></small></span><span class="recipient-type">{{ option.type === 'fornecedor' ? 'Fornecedor' : 'Cliente' }}</span></span></template></SearchCombobox></label><div v-if="recipient" class="selected-customer field-span-2"><span>{{ recipient.name.slice(0, 2).toUpperCase() }}</span><div><strong>{{ recipient.name }}</strong><p>{{ document(recipient.documento) }}<template v-if="recipient.cidade"> · {{ recipient.cidade }}/{{ recipient.uf }}</template></p><small v-if="recipient.logradouro">{{ recipient.logradouro }}, {{ recipient.numero }} — {{ recipient.bairro }}</small></div><em>{{ recipient.type === 'fornecedor' ? 'Fornecedor' : 'Cliente' }}</em></div></div></div>
      <div v-else-if="step === 3" class="invoice-step-content"><div class="section-title"><span><Package :size="21" /></span><div><h2>Produtos da nota</h2><p>Busque no catálogo, adicione itens e aplique o desconto total da NF-e.</p></div></div><div class="product-picker"><SearchCombobox v-model="selectedProduct" endpoint="/produtos" label-key="descricao" placeholder="Buscar produto por código, descrição ou NCM" search-placeholder="Digite código, produto ou NCM…" empty-text="Nenhum produto ativo encontrado."><template #selected="{ option }"><span class="selected-search-value"><strong>{{ option.codigo }} · {{ option.descricao }}</strong><small>{{ money(Number(option.valor_unitario || 0)) }}</small></span></template><template #option="{ option }"><span class="search-option"><span class="option-avatar product">{{ option.codigo?.slice(0, 3) || 'PRD' }}</span><span class="search-option-main"><strong>{{ option.descricao }}</strong><small>Cód. {{ option.codigo }}<template v-if="option.ncm"> · NCM {{ option.ncm }}</template></small></span><strong class="option-price">{{ money(Number(option.valor_unitario || 0)) }}</strong></span></template></SearchCombobox><button class="button button--primary" :disabled="!selectedProduct" @click="addProduct"><CirclePlus :size="17" /> Adicionar</button></div><div class="invoice-items"><article v-for="(item, index) in form.produtos" :key="item.id"><div class="item-head"><span>{{ Number(index) + 1 }}</span><div><strong>{{ item.descricao }}</strong><small>Cód. {{ item.codigo }}</small></div><button @click="form.produtos.splice(Number(index), 1)"><Trash2 :size="17" /></button></div><div class="item-fields"><label>NCM<input v-model="item.ncm" maxlength="8" placeholder="8 dígitos"></label><label>CFOP<input v-model="item.cfop" maxlength="4" placeholder="4 dígitos"></label><label>CSOSN<input v-model="item.csosn" maxlength="4" placeholder="Ex.: 0400"></label><label>Unidade<input v-model="item.unidade" placeholder="Ex.: UN"></label><label>Quantidade<input v-model.number="item.quantidade" type="number" min="1" step="1" placeholder="1"></label><label>Valor unitário<CurrencyInput v-model="item.valor_unitario" placeholder="0,00" /></label><div class="item-total"><small>Total</small><strong>{{ money(item.quantidade * item.valor_unitario) }}</strong></div></div></article><div v-if="!form.produtos.length" class="items-empty"><Package :size="25" /><p>Nenhum produto adicionado.</p></div></div><section class="invoice-financials"><div class="financial-heading"><div><strong>Totais da NF-e</strong><p>O desconto é aplicado sobre o subtotal de todos os itens.</p></div><span>Desconto total</span></div><div class="financial-content"><div class="financial-inputs"><label><span>Desconto da NF-e (R$)</span><CurrencyInput v-model="form.desconto" placeholder="0,00" /><small>Máximo: {{ money(subtotal) }}</small></label><label><span>Outras despesas (R$)</span><CurrencyInput v-model="form.outras_despesas" placeholder="0,00" /><small>Frete, seguro ou acréscimos</small></label></div><div class="financial-summary"><span><small>Subtotal dos produtos</small><strong>{{ money(subtotal) }}</strong></span><span class="discount-line"><small>Desconto</small><strong>− {{ money(Number(form.desconto || 0)) }}</strong></span><span><small>Outras despesas</small><strong>+ {{ money(Number(form.outras_despesas || 0)) }}</strong></span><span class="grand-total"><small>Total da NF-e</small><strong>{{ money(total) }}</strong></span></div></div></section></div>
      <div v-else-if="step === 4" class="invoice-step-content"><div class="section-title"><span><Truck :size="21" /></span><div><h2>Transporte e volumes</h2><p>Informe os dados logísticos quando aplicáveis.</p></div></div><div class="settings-form"><label class="field-span-2"><span>Modalidade do frete</span><select v-model="form.transportadora.modalidade_frete"><option value="9">Sem ocorrência de transporte</option><option value="0">Por conta do emitente</option><option value="1">Por conta do destinatário</option><option value="2">Por conta de terceiros</option></select></label><label class="field-span-2"><span>Transportadora</span><input v-model="form.transportadora.nome" placeholder="Razão social ou nome da transportadora"></label><label><span>CPF / CNPJ</span><input v-model="form.transportadora.documento" placeholder="Somente números"></label><label><span>Placa / UF</span><div class="inline-fields"><input v-model="form.transportadora.placa" maxlength="8" placeholder="ABC1D23"><input v-model="form.transportadora.uf_veiculo" maxlength="2" placeholder="UF"></div></label><label><span>Quantidade de volumes</span><input v-model.number="form.volumes.quantidade" type="number" min="0" placeholder="0"></label><label><span>Espécie</span><input v-model="form.volumes.especie" placeholder="Caixa, pacote…"></label><label><span>Peso bruto (kg)</span><input v-model.number="form.volumes.peso_bruto" type="number" min="0" step="0.001" placeholder="0,000"></label><label><span>Peso líquido (kg)</span><input v-model.number="form.volumes.peso_liquido" type="number" min="0" step="0.001" placeholder="0,000"></label></div></div>
      <div v-else class="invoice-step-content"><div class="section-title"><span><CheckCircle2 :size="21" /></span><div><h2>Revisão da NF-e</h2><p>Confira os dados antes de salvar ou transmitir à SEFAZ.</p></div></div><div class="review-grid"><article><small>Operação</small><strong>{{ natureza?.nome }}</strong><span>CFOP {{ natureza?.cfop_padrao }} · Série {{ form.serie }} · Nº {{ form.numero }}</span></article><article><small>Destinatário</small><strong>{{ recipient?.name }}</strong><span>{{ recipient?.documento }} · {{ recipient?.type === 'fornecedor' ? 'Fornecedor' : 'Cliente' }}</span></article><article><small>Itens</small><strong>{{ form.produtos.length }} produto(s)</strong><span>Subtotal {{ money(subtotal) }}</span></article><article><small>Valor total</small><strong class="review-total">{{ money(total) }}</strong><span>Desconto: {{ money(Number(form.desconto)) }}</span></article></div><div class="settings-form review-details"><label><span>Desconto total da NF-e (R$)</span><CurrencyInput v-model="form.desconto" placeholder="0,00" /></label><label><span>Outras despesas (R$)</span><CurrencyInput v-model="form.outras_despesas" placeholder="0,00" /></label><label class="field-span-2"><span>Informações complementares</span><textarea v-model="form.informacoes_complementares" rows="4" maxlength="2000" placeholder="Informações adicionais que devem constar na NF-e…"></textarea></label></div><div v-if="Object.keys(errors).length" class="form-alert">Revise os campos indicados pela API antes de tentar novamente.</div></div>
      <footer class="invoice-form-footer"><button class="button button--ghost" :disabled="step === 1" @click="step--"><ArrowLeft :size="17" /> Voltar</button><div><button v-if="step === 5" class="button button--ghost" :disabled="saving" @click="submit('rascunho')"><Save :size="17" /> Salvar pendente</button><button v-if="step < 5" class="button button--primary" @click="next">Continuar <ArrowRight :size="17" /></button><button v-else class="button button--primary" :disabled="saving" @click="submit('emitir')"><Send :size="17" />{{ saving ? 'Processando…' : 'Transmitir NF-e' }}</button></div></footer>
    </section>
  </div>
</template>
